# Tres formas de imprimir 1, 2 y 3
[1, 2, 3].each { |n| puts n }
for n in [1, 2, 3] do puts n end
1.upto(3) { |n| puts n }

def area(b, h = 1) = b * h / 2.0
puts area(6, 4) # 12.0
def par?(n) = n % 2 == 0
def repetir(n)
  n.times { |i| yield i if block_given? }
end
puts par?(4)    # true
repetir(3) { |i| puts "Paso #{i}" }
